package com.nth.desktop3d;

import android.app.*;
import android.content.*;
import android.graphics.*;
import android.net.Uri;
import android.os.*;
import android.view.*;
import android.view.accessibility.AccessibilityNodeInfo;
import android.widget.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import org.json.*;

/** Real renderer pixels, versioned scene packs, native editing and Android document intents. */
public final class ScenePacks093Smoke extends Trial093Support {
    public ScenePacks093Smoke(Instrumentation test,MainActivity activity,String output){super(test,activity,output);}
    public void run()throws Exception {snapshot();try{dataAndPixels();ui();}finally{restore();}}
    private byte[] photo()throws Exception {Bitmap b=Bitmap.createBitmap(64,96,Bitmap.Config.ARGB_8888);b.eraseColor(0xFF12394E);ByteArrayOutputStream out=new ByteArrayOutputStream();b.compress(Bitmap.CompressFormat.PNG,100,out);b.recycle();return out.toByteArray();}
    private LayeredScene.Document document()throws Exception {LayeredScene.Document d=new LayeredScene.Document();d.background=photo();LayeredScene.ObjectLayer o=new LayeredScene.ObjectLayer();o.kind="orb";o.name="Moving orb";o.size=.4f;d.objects.add(o);return d;}
    private void dataAndPixels(){main(()->{try{
        LayeredScene.Document d=document();d.objects.get(0).movement=2;d.objects.get(0).motionAmount=.8f;d.objects.get(0).motionSpeed=.7f;d.lightColor=0xFFAD55;d.lightIntensity=.8f;d.lightAngle=125;LayeredScene.Document copied=LayeredScene.copy(d),round=ScenePack.decode(ScenePack.encode(d));check(d.json().toString().equals(copied.json().toString())&&d.json().toString().equals(round.json().toString()),"Copy/pack lost assets, motion or lighting");JSONObject pack=new JSONObject(new String(ScenePack.encode(d),StandardCharsets.UTF_8));check(pack.length()==3&&!pack.has("settings")&&!pack.has("pages")&&!pack.has("note"),"A scene pack included desktop or personal data");
        JSONObject legacy=d.json();legacy.put("version",1);for(String key:new String[]{"animate","lightColor","lightIntensity","lightAngle"})legacy.remove(key);JSONObject object=legacy.getJSONArray("objects").getJSONObject(0);for(String key:new String[]{"movement","motionAmount","motionSpeed"})object.remove(key);LayeredScene.Document old=LayeredScene.parse(legacy);check(old.objects.get(0).movement==0&&old.lightIntensity==0&&old.animate,"Older scenes did not retain still/default lighting behavior");
        JSONObject bad=d.json();bad.getJSONArray("objects").getJSONObject(0).put("movement",4);rejectScene(bad);bad=d.json();bad.put("lightIntensity",1.1);rejectScene(bad);bad=d.json();bad.getJSONObject("background").put("sha256",String.join("",Collections.nCopies(64,"0")));rejectScene(bad);boolean rejected=false;try{ScenePack.decode(new JSONObject().put("format",DesktopBackup.FORMAT).put("version",4).toString().getBytes(StandardCharsets.UTF_8));}catch(Exception expected){rejected=true;}check(rejected,"A desktop backup was accepted as a scene pack");rejected=false;try{ScenePack.decode(new byte[ScenePack.MAX_BYTES+1]);}catch(Exception expected){rejected=true;}check(rejected,"Oversize scene pack was accepted");ScenePackFiles.prepare(activity,ScenePack.encode(d));check(ScenePack.decode(ScenePackFiles.read(activity)).json().toString().equals(d.json().toString()),"Pending export snapshot did not survive a new read");ScenePackFiles.clear(activity);
        LayerSceneView view=new LayerSceneView(activity);view.document(d);view.layout(0,0,300,480);set(view,"seconds",0f);Bitmap first=render(view);set(view,"seconds",5f);Bitmap second=render(view);check(diff(first,second)>300,"Per-object motion did not alter rendered pixels");first.recycle();second.recycle();view.lighting(false);set(view,"seconds",10f);first=render(view);set(view,"seconds",30f);second=render(view);check(diff(first,second)==0,"Reduced/background state did not freeze object motion");first.recycle();second.recycle();d.lightIntensity=0;first=render(view);d.lightIntensity=1;second=render(view);check(diff(first,second)>300,"Scene lighting did not alter object pixels");first.recycle();second.recycle();view.dispose();
    }catch(Exception e){throw new AssertionError(e);}});}
    private Bitmap render(View view){Bitmap b=Bitmap.createBitmap(300,480,Bitmap.Config.ARGB_8888);view.draw(new Canvas(b));return b;}
    private int diff(Bitmap a,Bitmap b){int[] x=new int[300*480],y=new int[x.length];a.getPixels(x,0,300,0,0,300,480);b.getPixels(y,0,300,0,0,300,480);int changes=0;for(int i=0;i<x.length;i++)if(x[i]!=y[i])changes++;return changes;}
    private void rejectScene(JSONObject scene){boolean rejected=false;try{LayeredScene.parse(scene);}catch(Exception expected){rejected=true;}check(rejected,"Invalid motion/light/asset scene was accepted");}
    private void slider(String title,int progress){main(()->{SeekBar bar=(SeekBar)find(v->v instanceof SeekBar&&title.contentEquals(Objects.toString(v.getContentDescription(),"")));check(bar!=null,"Missing slider: "+title);Bundle args=new Bundle();args.putFloat(AccessibilityNodeInfo.ACTION_ARGUMENT_PROGRESS_VALUE,progress);check(bar.performAccessibilityAction(AccessibilityNodeInfo.AccessibilityAction.ACTION_SET_PROGRESS.getId(),args),"Could not adjust "+title);});}
    private Instrumentation.ActivityMonitor picker(String action,String type,File file)throws Exception {IntentFilter filter=new IntentFilter(action);filter.addCategory(Intent.CATEGORY_OPENABLE);filter.addDataType(type);return test.addMonitor(filter,new Instrumentation.ActivityResult(Activity.RESULT_OK,new Intent().setData(Uri.fromFile(file))),true);}
    private void ui()throws Exception {
        File export=new File(activity.getCacheDir(),"smoke093-export.nth3dscene"),imported=new File(activity.getCacheDir(),"smoke093-import.nth3dscene");LayeredScene.Document next=document();next.objects.get(0).name="Imported orb";next.objects.get(0).movement=3;next.lightIntensity=.65f;next.lightColor=0x79EF91;try(FileOutputStream out=new FileOutputStream(imported)){out.write(ScenePack.encode(next));}
        main(()->{try{call(activity,"closePanel");LayeredScene.Document d=document();LayeredScene.write(activity,d,true);LayeredScene.write(activity,new LayeredScene.Document(),false);store.pages.get(store.page).clear();store.preferences.edit().putInt("wallpaper_source",3).putString("note","Shared note stays").putBoolean("shuffle_enabled",false).apply();store.save();call(activity,"applySettings",true);call(activity,"showSceneCreator");}catch(Exception e){throw new AssertionError(e);}});await(()->field(activity,"sceneComposer")!=null,"Scene creator did not open");SceneComposer composer=(SceneComposer)field(activity,"sceneComposer");main(()->composer.step(1));click("Object motion: Still");slider("Object motion amount",60);slider("Object motion speed",70);check(composer.document.objects.get(0).movement==1&&Math.abs(composer.document.objects.get(0).motionAmount-.6f)<.001,"Object motion controls did not change the draft");main(()->composer.step(2));slider("Scene light strength",80);click("Scene light color: Ice blue");slider("Scene light direction",225);check(composer.document.lightColor==0xFFAD55&&Math.abs(composer.document.lightIntensity-.8f)<.001&&composer.document.lightAngle==225,"Scene lighting controls were not applied");capture("scenepacks093-editor");
        Instrumentation.ActivityMonitor save=picker(Intent.ACTION_CREATE_DOCUMENT,"application/json",export);try{click("Export scene pack");await(()->save.getHits()>0&&export.length()>0,"Export did not use the Android document intent");filesIdle();LayeredScene.Document saved=ScenePack.decode(java.nio.file.Files.readAllBytes(export.toPath()));check(saved.objects.get(0).movement==1&&saved.lightColor==0xFFAD55,"Document export lost the edited scene");}finally{test.removeMonitor(save);}
        click("Apply scene");await(()->field(activity,"sceneComposer")==null,"Applying did not close the creator");filesIdle();LayeredScene.Document applied=LayeredScene.read(activity,false);check(applied.objects.get(0).movement==1&&applied.lightAngle==225&&model.value("wallpaper_source")==3,"Applying lost the scene motion/light controls");String active=applied.json().toString();capture("scenepacks093-applied");
        main(()->call(activity,"showSceneCreator"));await(()->field(activity,"sceneComposer")!=null,"Could not reopen the creator");SceneComposer current=(SceneComposer)field(activity,"sceneComposer");main(()->current.step(0));String before=current.document.json().toString();
        Instrumentation.ActivityMonitor open=picker(Intent.ACTION_OPEN_DOCUMENT,"*/*",imported);try{click("Import scene pack");await(()->field(activity,"scenePackConfirmation")!=null,"Import did not show a review dialog");systemClick("Cancel");check(before.equals(current.document.json().toString())&&active.equals(LayeredScene.read(activity,false).json().toString()),"Cancel replaced a draft or applied wallpaper");click("Import scene pack");await(()->field(activity,"scenePackConfirmation")!=null,"Second import did not show its review dialog");systemClick("Import");await(()->{SceneComposer c=(SceneComposer)field(activity,"sceneComposer");return c!=null&&!c.document.objects.isEmpty()&&c.document.objects.get(0).name.equals("Imported orb");},"Imported pack was not opened as a draft");check(active.equals(LayeredScene.read(activity,false).json().toString())&&"Shared note stays".equals(store.preferences.getString("note","")),"Import changed the active scene or shared notes before Apply");capture("scenepacks093-imported-draft");}finally{test.removeMonitor(open);export.delete();imported.delete();}
    }
}
